const express = require('express');
const crypto = require('crypto');
const app = express();

const ENCRYPTION_KEY = Buffer.from(process.env.ENC_KEY || 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6', 'hex');
const IV_LENGTH = 16;
const BLOCK_SIZE = 16;

// Session token encryption using AES-128-CBC
function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-128-cbc', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8');
  encrypted = Buffer.concat([encrypted, cipher.final()]);
  return iv.toString('hex') + ':' + encrypted.toString('hex');
}

function decrypt(encryptedText) {
  const parts = encryptedText.split(':');
  if (parts.length !== 2) {
    throw new Error('Invalid token format');
  }
  const iv = Buffer.from(parts[0], 'hex');
  const encryptedData = Buffer.from(parts[1], 'hex');

  if (encryptedData.length % BLOCK_SIZE !== 0) {
    throw new Error('Invalid token length');
  }

  const decipher = crypto.createDecipheriv('aes-128-cbc', ENCRYPTION_KEY, iv);
  let decrypted = decipher.update(encryptedData);
  // This will throw a specific padding error if padding is invalid
  decrypted = Buffer.concat([decrypted, decipher.final()]);
  return decrypted.toString('utf8');
}

// Middleware to validate session tokens
app.use('/api', (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) {
    return res.status(401).json({ error: 'Missing session token' });
  }

  try {
    const sessionData = decrypt(token);
    const parsed = JSON.parse(sessionData);
    req.session = parsed;
    next();
  } catch (err) {
    // VULNERABILITY: Different error responses for padding vs. other errors
    if (err.message.includes('bad decrypt') || err.message.includes('wrong final block')) {
      // Padding error - returns 403
      return res.status(403).json({ error: 'Token validation failed', code: 'PADDING_ERROR' });
    } else if (err instanceof SyntaxError) {
      // Valid decryption but invalid JSON - returns 422
      return res.status(422).json({ error: 'Token validation failed', code: 'FORMAT_ERROR' });
    } else {
      // Other errors - returns 400
      return res.status(400).json({ error: 'Token validation failed', code: 'GENERAL_ERROR' });
    }
  }
});

app.get('/api/profile', (req, res) => {
  res.json({ user: req.session.username, role: req.session.role });
});

app.get('/api/admin/users', (req, res) => {
  if (req.session.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient privileges' });
  }
  res.json({ users: ['alice', 'bob', 'charlie'] });
});

app.post('/auth/login', express.json(), (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  if (username === 'admin' && password === process.env.ADMIN_PASS) {
    const token = encrypt(JSON.stringify({ username: 'admin', role: 'admin', iat: Date.now() }));
    return res.json({ token });
  }
  if (username && password === 'user123') {
    const token = encrypt(JSON.stringify({ username, role: 'user', iat: Date.now() }));
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

// Health check endpoint (unauthenticated)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Session service listening on port ${PORT}`);
});
